-- T1.3 reviewed import artifact generated from the G array in index.html.
-- Source order is retained in sort_order; examples are null because the source HTML has no separate example field.
-- Review and apply only after the sort_order migration; this file is not run by migrations automatically.
begin;

do $$
begin
  if exists (select 1 from public.glossary_entries) then
    raise exception 'T1.3 import expects an empty glossary_entries table';
  end if;
end;
$$;

insert into public.glossary_entries (
  term, translation_es, definition_en, example_en, category, source_reference, sort_order
) values
  ('Advanced persistent threat (APT)', 'amenaza persistente avanzada', 'An APT is a planned attack on a specific organization. The attacker works to get into its network and may stay there for a long time to find important information.', null, 'Threat', 'Sophos Threatsaurus, p. 6', 1),
  ('Adware', 'software publicitario', 'Adware displays advertising banners or pop-ups while you use an application. It can fund free software, but becomes a problem if it is installed without consent, spreads into other applications, tracks browsing without permission, hijacks the browser, or is difficult to uninstall.', null, 'Threat', 'Sophos Threatsaurus, p. 7', 2),
  ('Anonymizing proxy', 'proxy anonimizador', 'An anonymizing proxy hides a user''s web browsing activity and is often used to bypass web security filters. In an organization, that can allow access to unauthorized pages and create security or legal liability risks.', null, 'Threat', 'Sophos Threatsaurus, p. 8', 3),
  ('Autorun worm', 'gusano de ejecución automática', 'An autorun worm uses the Windows AutoRun feature to start automatically when the device storing it is connected to a computer. USB drives are a common way it spreads; attackers have also exploited the similar AutoPlay feature on removable media.', null, 'Threat', 'Sophos Threatsaurus, p. 9', 4),
  ('Backdoor Trojan', 'troyano de puerta trasera', 'A backdoor Trojan may disguise itself as legitimate software or reach a computer through a spam link or malicious webpage. Once running, it can let its sender remotely run programs, access or change files, record keystrokes, upload files, or send spam from the computer.', null, 'Threat', 'Sophos Threatsaurus, p. 10', 5),
  ('Boot sector malware', 'malware del sector de arranque', 'Boot sector malware replaces or modifies the program that a computer uses to start, often keeping the original elsewhere on the disk. The infected boot program runs at startup, sometimes before the operating system, which can help the malware conceal itself.', null, 'Threat', 'Sophos Threatsaurus, p. 11', 6),
  ('Botnet', 'red de bots', 'A botnet is a group of computers infected with malicious software and controlled remotely by a hacker, often without their owners'' knowledge. The group can be used to send spam or launch distributed denial-of-service attacks, and access to it may be shared or sold.', null, 'Threat', 'Sophos Threatsaurus, p. 12', 7),
  ('Browser hijacker', 'secuestrador de navegador', 'A browser hijacker changes a browser''s default homepage or search engine without permission. Some hijackers make these settings difficult to restore or redirect clicks, and may be used to increase advertising revenue or a site''s ranking in search results.', null, 'Threat', 'Sophos Threatsaurus, p. 13', 8),
  ('Brute force attack', 'ataque de fuerza bruta', 'A brute force attack tries a very large number of possible passwords or keyword combinations to gain unauthorized access to a system, file, or protected message. Attackers commonly use computer programs to automate these attempts.', null, 'Threat', 'Sophos Threatsaurus, p. 14', 9),
  ('Buffer overflow', 'desbordamiento de búfer', 'A buffer overflow happens when a program gets more information than it can handle. This can make the program stop working or let an attacker run harmful code.', null, 'Threat', 'Sophos Threatsaurus, p. 15', 10),
  ('Command and control center (C&C)', 'centro de mando y control', 'A command and control center is a computer used to control a botnet of compromised computers. From it, a hacker can instruct many infected machines to carry out the same activity, such as a distributed denial-of-service attack.', null, 'Threat', 'Sophos Threatsaurus, p. 16', 11),
  ('Cookie', 'cookie', 'A cookie is a small file a website places on your computer so it can remember details such as preferences or login information. Cookies can also track visits and browsing interests for advertising, which may affect privacy, but they cannot infect a computer.', null, 'Threat', 'Sophos Threatsaurus, p. 17', 12),
  ('Data leakage', 'fuga de datos', 'Data leakage is the unauthorized exposure of information, whether accidental or deliberate. It can expose confidential details about an organization, its workers, customers, or the public, and may result in data theft or data loss.', null, 'Threat', 'Sophos Threatsaurus, p. 18', 13),
  ('Data loss', 'pérdida de datos', 'Data loss is the accidental misplacement of data, rather than its deliberate theft. It often happens when a device such as a laptop, phone, or USB drive is lost; without protection such as encryption, the data could fall into the wrong hands.', null, 'Threat', 'Sophos Threatsaurus, p. 19', 14),
  ('Data theft', 'robo de datos', 'Data theft is the deliberate taking of information, either by someone inside an organization or by an outside criminal. It can involve malware that accesses a computer and captures details such as usernames and passwords, or the theft of a device that stores data.', null, 'Threat', 'Sophos Threatsaurus, p. 20', 15),
  ('Denial-of-service attack (DoS)', 'ataque de denegación de servicio', 'A denial-of-service attack overloads or shuts down a computer or service so legitimate users cannot access it, often making a website unavailable. The attack does not necessarily steal or compromise data, but the interruption can be costly; a botnet can make it distributed (DDoS).', null, 'Threat', 'Sophos Threatsaurus, p. 21', 16),
  ('DNS hijacking', 'secuestro de DNS', 'DNS helps your device find websites. In DNS hijacking, someone changes those settings so you may be sent to a fake website or blocked from security updates.', null, 'Threat', 'Sophos Threatsaurus, p. 22', 17),
  ('Document malware', 'malware en documentos', 'Document malware hides malicious content in a document and exploits a vulnerability in the application used to open or edit it. Carefully crafted Word, Excel, or PDF files can therefore infect or compromise a computer when opened in a vulnerable program.', null, 'Threat', 'Sophos Threatsaurus, p. 23', 18),
  ('Drive-by download', 'descarga no autorizada', 'A drive-by download infects a computer when a user visits a malicious or compromised website, sometimes without clicking anything or realizing it. The malware can exploit weaknesses in the browser or its plugins to download and run.', null, 'Threat', 'Sophos Threatsaurus, p. 24', 19),
  ('Email malware', 'malware por correo', 'Email malware is malicious software distributed through email. It may arrive as an attachment that runs when opened, or the message may link to a malicious website; attackers have often used email to direct people to such sites.', null, 'Threat', 'Sophos Threatsaurus, p. 25', 20),
  ('Exploit', 'exploit', 'An exploit takes advantage of a vulnerability in software to access or infect a computer. It often targets a particular application flaw; a zero-day exploit is used before the software vendor knows about the vulnerability or has a patch available.', null, 'Threat', 'Sophos Threatsaurus, p. 26', 21),
  ('Fake antivirus', 'antivirus falso', 'Fake antivirus malware reports threats that do not exist to frighten people into installing malicious software or paying for unnecessary registration or cleanup. It is also called scareware and is often distributed through deceptive websites or links in spam.', null, 'Threat', 'Sophos Threatsaurus, p. 27', 22),
  ('Hacktivism', 'hacktivismo', 'Hacktivism is hacking carried out for political or social purposes, often to make a point against an organization, government, or individual. Tactics described in the Threatsaurus include defacing websites, redirecting traffic, launching denial-of-service attacks, and stealing information.', null, 'Threat', 'Sophos Threatsaurus, p. 28', 23),
  ('Hoax', 'engaño, bulo', 'A hoax is a false, unsubstantiated claim intended to trick or defraud people. A hoax message may invent a dangerous malware warning or urge recipients to forward it; widespread forwarding can consume bandwidth, overload mail servers, or distract from real threats.', null, 'Threat', 'Sophos Threatsaurus, p. 29', 24),
  ('Honeypot', 'trampa, señuelo', 'A honeypot is a security trap used to detect hacking attempts or collect malware samples. It may be a machine set up to capture malware or a fake network service, such as a web server, that records incoming attacks.', null, 'Threat', 'Sophos Threatsaurus, p. 30', 25),
  ('Internet worm', 'gusano', 'An Internet worm is malware that copies itself across the Internet or local networks without attaching to a carrier program or file. It can spread rapidly; some worms also open a backdoor that lets hackers control a computer or use it to send spam.', null, 'Threat', 'Sophos Threatsaurus, p. 31', 26),
  ('Keylogging', 'registro de teclas', 'Keylogging is the secret recording of keystrokes by an unauthorized third party. Malware may use it to capture usernames, passwords, credit card details, and other sensitive information as a person types.', null, 'Threat', 'Sophos Threatsaurus, p. 32', 27),
  ('Malware', 'software malicioso', 'Malware is the general name for malicious software. It includes viruses, worms, Trojans, and spyware, so antivirus software is intended to detect a wider range of threats than viruses alone.', null, 'Threat', 'Sophos Threatsaurus, p. 33', 28),
  ('Mobile phone malware', 'malware para celulares', 'Mobile phone malware is malicious software intended to run on devices such as smartphones and tablets. It may steal confidential information, pose as fake antivirus software, or send messages or place calls to premium-rate numbers.', null, 'Threat', 'Sophos Threatsaurus, p. 34', 29),
  ('Parasitic virus', 'virus parásito', 'A parasitic virus, also called a file virus, attaches itself to a program. When that infected program starts, the virus code runs and can then pass control back to the original program while using the program''s permissions to make changes or copy itself.', null, 'Threat', 'Sophos Threatsaurus, p. 35', 30),
  ('Patches', 'parches', 'Patches are software add-ons that fix bugs, including security vulnerabilities, in operating systems or applications. Applying them promptly closes weaknesses that malware and hackers may otherwise exploit.', null, 'Threat', 'Sophos Threatsaurus, p. 36', 31),
  ('Phishing', 'phishing, suplantación', 'Phishing deceives recipients into sharing sensitive information with a cybercriminal. A message may pretend to come from a bank, social network, online service, or a department in the recipient''s organization; attachments can also infect a computer if opened.', null, 'Threat', 'Sophos Threatsaurus, p. 37', 32),
  ('Potentially unwanted application (PUA)', 'aplicación potencialmente no deseada', 'A potentially unwanted application is not necessarily malicious and may be useful in some situations, but it may be unsuitable for a business environment or create security concerns. Examples include adware, remote PC administration tools, and vulnerability scanners.', null, 'Threat', 'Sophos Threatsaurus, p. 38', 33),
  ('Ransomware', 'ransomware, secuestro de datos', 'Ransomware is software that denies access to files or a computer until a ransom is paid. It can hold data hostage by placing it in a password-protected or encrypted form, making the original files inaccessible.', null, 'Threat', 'Sophos Threatsaurus, p. 39', 34),
  ('Rootkit', 'rootkit', 'A rootkit is software that hides programs or processes running on a computer. Malware may use one to conceal tools such as keystroke loggers or password sniffers, or to let hackers use the computer without the owner''s knowledge.', null, 'Threat', 'Sophos Threatsaurus, p. 40', 35),
  ('Social engineering', 'ingeniería social', 'Social engineering uses deception to make a person perform an action chosen by an attacker. This may mean opening a malicious webpage or attachment, or revealing a username or password that can help the attacker steal data.', null, 'Threat', 'Sophos Threatsaurus, p. 41', 36),
  ('Social networking', 'redes sociales', 'Social networking websites let people communicate and share information, but attackers can use them to spread malware or steal personal details. Information posted online may help with social engineering or security questions, and a compromised friend''s account can spread malicious content.', null, 'Threat', 'Sophos Threatsaurus, p. 42', 37),
  ('Spam', 'correo basura', 'Spam is unsolicited bulk email sent to inboxes, like electronic junk mail. It can distribute malware or scams, consume bandwidth and storage, waste staff time, and make important messages easier to overlook; spammers may disguise messages or use compromised accounts.', null, 'Threat', 'Sophos Threatsaurus, p. 43', 38),
  ('Spearphishing', 'phishing dirigido', 'Spearphishing is phishing aimed at specific people in an organization, using spoofed messages to persuade them to reveal sensitive information or credentials. The message may appear to come from a colleague or trusted department and link to a fake company site.', null, 'Threat', 'Sophos Threatsaurus, p. 44', 39),
  ('Spoofing (email)', 'suplantación de correo', 'Email spoofing forges the sender address so a message appears to come from a trusted person or organization, including someone inside the recipient''s organization. Criminals use it to support phishing, direct people to bogus sites, or conceal who sent a scam.', null, 'Threat', 'Sophos Threatsaurus, p. 45', 40),
  ('Spyware', 'software espía', 'Spyware lets advertisers or hackers gather sensitive information without permission. It may track a person''s activity, such as websites visited, and send it to unauthorized parties; running spyware can also use memory and processing capacity and slow or crash a computer.', null, 'Threat', 'Sophos Threatsaurus, p. 46', 41),
  ('SQL injection', 'inyección SQL', 'Some websites use databases to store information. In an SQL injection attack, a criminal enters special text into a website form to trick the database into showing or changing information.', null, 'Threat', 'Sophos Threatsaurus, p. 47', 42),
  ('Suspicious files and behavior', 'archivos y comportamiento sospechosos', 'An endpoint security scanner may label a file suspicious when it has questionable characteristics or behaves in a questionable way, such as copying itself to a system folder. Runtime protection can watch running programs and block activity that appears malicious.', null, 'Threat', 'Sophos Threatsaurus, p. 48', 43),
  ('Trojan (Trojan horse)', 'troyano', 'A Trojan pretends to be legitimate software but secretly performs harmful functions. Once installed, it may add spyware or other malware, compromise the computer, or damage data while the user believes they are running an ordinary program.', null, 'Threat', 'Sophos Threatsaurus, p. 49', 44),
  ('Virus', 'virus', 'A virus is a malicious program that can spread by attaching itself to other files or to code that runs when certain files are opened. It may display messages, steal data, or give hackers control, and can arrive in an email attachment, download, or USB drive.', null, 'Threat', 'Sophos Threatsaurus, p. 50', 45),
  ('Vulnerability', 'vulnerabilidad', 'A vulnerability is a bug or weakness in software that hackers can exploit to compromise a computer. Vendors may issue patches to fix it; an attack that uses a vulnerability before it is known or patched is called a zero-day attack.', null, 'Threat', 'Sophos Threatsaurus, p. 51', 46),
  ('Zombie', 'zombi', 'A zombie is an infected computer that a hacker controls remotely over the Internet, usually without the user''s knowledge. It is part of a botnet and may be used to send spam, launch denial-of-service attacks, or infect other systems.', null, 'Threat', 'Sophos Threatsaurus, p. 52', 47),
  ('Anti-malware', 'antimalware', 'Anti-malware software scans for viruses, Trojans, worms, spyware, and other malicious programs. It can compare files with known malware identities, analyze program behavior for unknown threats, and check files continuously as they are opened or in a scan started on demand.', null, 'Security tool', 'Sophos Threatsaurus, p. 54', 48),
  ('Anti-spam', 'antispam', 'Anti-spam software evaluates messages using clues such as block lists, links, sender details, keywords, and suspicious patterns. Depending on its settings, it can block or delete likely spam, and it needs updated rules to recognize spammers'' changing techniques.', null, 'Security tool', 'Sophos Threatsaurus, p. 55', 49),
  ('Appliances', 'equipos de seguridad', 'A security appliance combines hardware and software in one solution that can be connected to a network instead of installing each program separately. Email, web, and UTM appliances commonly sit at the gateway and filter traffic for threats such as malware, spam, and data loss.', null, 'Security tool', 'Sophos Threatsaurus, p. 56', 50),
  ('Application control', 'control de aplicaciones', 'Application control lets an organization restrict which programs can run on business computers or networks. Controlling applications such as file-sharing tools, games, media players, remote administration tools, or messaging clients can reduce the risk of malware and data loss.', null, 'Security tool', 'Sophos Threatsaurus, p. 57', 51),
  ('Device control', 'control de dispositivos', 'Device control governs the use of removable storage, optical drives, and wireless networking protocols. An organization can apply a central policy to decide which devices may connect, helping manage data loss risks and malware spread through USB drives.', null, 'Security tool', 'Sophos Threatsaurus, p. 58', 52),
  ('Encryption', 'cifrado', 'Encryption transforms data so it can be read only by someone with the right key or password to decrypt it. It can protect files on computers, removable media, email, networks, and cloud storage, including data accessed by authorized mobile workers.', null, 'Security tool', 'Sophos Threatsaurus, p. 59', 53),
  ('Endpoint security', 'seguridad de dispositivos', 'Endpoint security protects computers and other devices against a range of security, productivity, and compliance threats, while allowing their security to be managed centrally. A product may combine tools such as antivirus, firewall, device and application control, encryption, web security, and patch management.', null, 'Security tool', 'Sophos Threatsaurus, p. 60', 54),
  ('Firewall', 'cortafuegos', 'A firewall acts as a barrier that inspects incoming and outgoing network traffic and allows or blocks it according to set criteria. It may protect a whole network at its boundary or run on an individual computer, and can filter by addresses, ports, protocols, or packet attributes.', null, 'Security tool', 'Sophos Threatsaurus, p. 61', 55),
  ('HTTPS scanning', 'análisis HTTPS', 'HTTPS scanning decrypts encrypted web traffic, checks it for malicious content, and then encrypts it again. The scan can find and remove threats automatically without a person viewing the traffic''s contents.', null, 'Security tool', 'Sophos Threatsaurus, p. 62', 56),
  ('Intrusion prevention system (IPS)', 'sistema de prevención de intrusiones', 'An intrusion prevention system monitors a network or computer systems for malicious activity. It can record activity, try to block it, and report it to network administrators to help prevent infections.', null, 'Security tool', 'Sophos Threatsaurus, p. 63', 57),
  ('IPsec', 'IPsec', 'IPsec helps protect information sent between computers over a network. It checks who is connected and scrambles the information so other people cannot easily read it.', null, 'Security tool', 'Sophos Threatsaurus, p. 64', 58),
  ('Mobile device security', 'seguridad de dispositivos móviles', 'Mobile device security is the policies, procedures, and tools used to protect mobile devices and the data on them. It includes keeping software current, being cautious about new apps, using current security software, and investigating suspicious activity; management systems can centralize some tasks.', null, 'Security tool', 'Sophos Threatsaurus, p. 65', 59),
  ('Network access control (NAC)', 'control de acceso a la red', 'Network access control protects a network and its information by checking users and devices before granting access. It can authenticate them, assess whether a computer meets security requirements, and apply access rules based on the user''s role.', null, 'Security tool', 'Sophos Threatsaurus, p. 66', 60),
  ('Runtime protection', 'protección en tiempo de ejecución', 'Runtime protection watches programs while they run and blocks activity that may be malicious, such as changes that could make malware start automatically. Related systems can monitor code behavior or catch attempts to exploit buffer-overflow vulnerabilities.', null, 'Security tool', 'Sophos Threatsaurus, p. 67', 61),
  ('Unified threat management (UTM)', 'gestión unificada de amenazas', 'Unified threat management (UTM) is one security device or service that combines several protections, such as a firewall and checks for spam or harmful software.', null, 'Security tool', 'Sophos Threatsaurus, p. 68', 62),
  ('URL filtering', 'filtrado de URL', 'URL or web content filtering lets an organization block particular websites or whole categories of sites. Restricting access can reduce the risk of users encountering web-based malware and phishing attacks.', null, 'Security tool', 'Sophos Threatsaurus, p. 69', 63),
  ('VPN', 'red privada virtual', 'A virtual private network connects remote computers or offices to a central network over the Internet. Remote users typically authenticate with a password or key so they can communicate with or access the organization''s servers securely.', null, 'Security tool', 'Sophos Threatsaurus, p. 70', 64),
  ('Web application control', 'control de aplicaciones web', 'Web application control blocks or limits web applications that an organization considers unwanted or risky, such as peer-to-peer file sharing or instant messaging. It can also ensure critical applications receive suitable bandwidth.', null, 'Security tool', 'Sophos Threatsaurus, p. 71', 65),
  ('Web application firewall (WAF)', 'firewall de aplicaciones web', 'A web application firewall scans activity directed at web servers to identify probes and attacks. It protects servers that are accessible from the Internet and may combine functions such as content and spam filtering, intrusion detection, and antivirus.', null, 'Security tool', 'Sophos Threatsaurus, p. 72', 66);

commit;
